import{c as t,Q as o,j as s,m as i}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":".claude/skills/ 稽核（弱模型長期自主運作視角）","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-07-03-harness-audit-appendix/inv-skills.md","filePath":"research/reports/2026-07-03-harness-audit-appendix/inv-skills.md","lastUpdated":1785909234000}'),d={name:"research/reports/2026-07-03-harness-audit-appendix/inv-skills.md"};function r(a,e,l,n,c,p){return o(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="claude-skills-稽核-弱模型長期自主運作視角" tabindex="-1">.claude/skills/ 稽核（弱模型長期自主運作視角） <a class="header-anchor" href="#claude-skills-稽核-弱模型長期自主運作視角" aria-label="Permalink to &quot;.claude/skills/ 稽核（弱模型長期自主運作視角）&quot;">​</a></h1><p>範圍：31 個 skill 目錄 + RESOLVER.md + dependency-graph.json，唯讀盤點。</p><h2 id="_1-skill-md-體積排行-bytes-lines-—-top-5-最肥" tabindex="-1">1. SKILL.md 體積排行（bytes, lines）— top 5 最肥 <a class="header-anchor" href="#_1-skill-md-體積排行-bytes-lines-—-top-5-最肥" aria-label="Permalink to &quot;1. SKILL.md 體積排行（bytes, lines）— top 5 最肥&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rank</th><th>bytes</th><th>lines</th><th>file</th></tr></thead><tbody><tr><td>1</td><td>20857</td><td>504</td><td>pilot-review/SKILL.md</td></tr><tr><td>2</td><td>20520</td><td>366</td><td>harness-meta/SKILL.md</td></tr><tr><td>3</td><td>18393</td><td>338</td><td>media-research/SKILL.md</td></tr><tr><td>4</td><td>16418</td><td>331</td><td>research-hub/SKILL.md</td></tr><tr><td>5</td><td>16194</td><td>217</td><td>autoresearch/SKILL.md</td></tr></tbody></table><p>全 31 筆完整清單見下（bytes desc）： quality-pipeline 15411/406、sre 15197/334、sia 13930/281、autoload-evolution 13161/281、finops 12313/260、review-hub 10859/197、sonnet-pilot 10478/217、multi-mode-skill 10185/134、opus-pilot 8994/162、media-transcribe 8760/212、pr-guard 8592/232、fable-pilot 8549/121、skill-evolution 8500/218、gap-vote 8094/189、haiku-pilot 7407/169、security-compliance 7369/180、verified-merge 7128/150、tech-strategy 6881/180、dreaming-consolidator 6361/103、db-ops 6255/121、ship-review 5022/106、fable5-harness 4913/74、handoff 4494/71、spec-implement 4226/102、overnight-research 4173/82、diagram-gen 2967/74。</p><p><strong>風險</strong>：<code>pilot-review</code>（504 行）與 <code>harness-meta</code>（366 行）遠超其他 skill，弱模型（Haiku/Sonnet）在長 SKILL.md 中段內容易被截斷/漏讀（core.md OBSERVE「工具輸出截斷不得假設為空」同理適用於長文件本身的注意力衰減，非機械可驗證但為已知弱點）。</p><h2 id="_2-trigger-重疊-職責邊界模糊" tabindex="-1">2. Trigger 重疊 / 職責邊界模糊 <a class="header-anchor" href="#_2-trigger-重疊-職責邊界模糊" aria-label="Permalink to &quot;2. Trigger 重疊 / 職責邊界模糊&quot;">​</a></h2><p>各 skill 皆有 <code>Use when</code> / <code>Do NOT use for</code> 顯式互斥宣告（本身設計良好），但以下配對<strong>字面觸發詞或功能描述高度相似</strong>，弱模型仍可能選錯：</p><ul><li><strong><code>harness-meta</code> vs <code>fable5-harness</code></strong>（harness-meta/SKILL.md:38-42, fable5-harness/SKILL.md:2-3）：两者都用「四層架構」「L1-L4」字眼；harness-meta 稱「四層架構稽核（L1-L4）」也是其 trigger 之一，僅靠 Do NOT use 反向排除區分（稽核工具箱 vs 契約應用入口），無正向決策樹判準。</li><li><strong><code>media-research</code> vs <code>media-transcribe</code></strong>（media-research/SKILL.md description, media-transcribe/SKILL.md description）：都吃 Twitter/X、YouTube URL；區分靠「文字分析 vs 完整逐字稿」語意判斷，無 URL pattern/關鍵字層級的機械分流規則。</li><li><strong><code>quality-pipeline</code> vs <code>pilot-review</code> vs <code>ship-review</code></strong>：三者皆為「multi-mode-agent fan-out + haiku/sonnet/opus/fable 分工 + GO/NO-GO 或 verdict」模式，功能骨架幾乎相同，僅審查焦點（品質閘道 / 四維評審 / 上線前）不同，RESOLVER.md 未提供三者共同決策樹（僅各自條列，見 RESOLVER.md:208-235, 259-262 附近段落分散）。</li><li><strong><code>{haiku,sonnet,opus,fable}-pilot</code></strong>：四份 description 為同一模板複製（僅代換模型名），&quot;routine tasks&quot; / &quot;cost-sensitive&quot; 等排除詞無具體檔案數/token 數字門檻寫在 description 層（門檻藏在各 SKILL.md 內文，如 haiku-pilot/SKILL.md:100-101），弱模型讀 description 選 skill 時看不到門檻。</li><li><strong><code>verified-merge</code> vs <code>pr-guard</code> vs <code>ship-review</code></strong>：merge/PR gate 職責相近，靠文字排除（verified-merge Do NOT use for 開 PR/commit；pr-guard Do NOT use for 一般 review/gate-then-merge），無單一速查表整合三者觸發優先序。</li></ul><h2 id="_3-硬編碼模型名-effort-換模型世代即過時風險" tabindex="-1">3. 硬編碼模型名 / effort（換模型世代即過時風險） <a class="header-anchor" href="#_3-硬編碼模型名-effort-換模型世代即過時風險" aria-label="Permalink to &quot;3. 硬編碼模型名 / effort（換模型世代即過時風險）&quot;">​</a></h2><p>Grep 結果 98 處命中版本化模型名（claude-sonnet-4-6 / opus-4-8 / haiku-4-5 / fable-5 等），3 處硬編碼 effort 值。<strong>多數命中帶有「重驗機制」或「provenance 標記」</strong>（如 harness-meta/SKILL.md:53-59 模型事實基準表本身设计为需重驗、sonnet-pilot/SKILL.md:21 明寫 &quot;evaluator 為當時的 Opus 4.7——provenance 保留，重跑時改用現役最強 evaluator&quot;），非全部裸硬編碼。</p><p><strong>真正無重驗保護、description 層直接寫版本號的高風險項</strong>：</p><ul><li>opus-pilot/SKILL.md:3 — description 直寫 &quot;Opus 4.8 ceiling-elevation mode&quot;</li><li>sonnet-pilot/SKILL.md:3 — description 直寫 &quot;Sonnet 4.6 quality-first mode&quot;</li><li>haiku-pilot/SKILL.md:3 — description 直寫 &quot;Haiku 4.5 cost-first mode&quot;</li><li>fable-pilot/SKILL.md:3 — description 直寫 &quot;Fable 5（Mythos-class）&quot;</li><li>影響：這 4 個 skill 的<strong>唯一觸發判準之一是 description 裡的版本字串</strong>；模型世代升級（如 Sonnet 5 已於 harness-meta/SKILL.md:55, 66 出現且標注「CC <code>sonnet</code> alias 現解析至此」）後，若 pilot skill description 未同步更新，<code>Use when user types sonnet, sonnet-pilot, Sonnet mode</code> 這類<strong>觸發詞本身仍成立</strong>但 skill 內文假設的定價/能力基準（sonnet-pilot/SKILL.md:21 的 A/B/C benchmark）已對不上新世代 Sonnet 5，弱模型無法自行察覺基準過期。</li><li>sia/REFERENCE.md:44-46, 66-67 — <code>haiku→claude-haiku-4-5</code>、<code>sonnet→claude-sonnet-4-6</code>、<code>opus→claude-opus-4-8</code> 映射表硬編碼於獨立 REFERENCE.md，無 grep 重驗腳本掛鉤（harness-meta/SKILL.md:331 有一行類似 grep 但只驗 harness-meta 自身）。</li><li>finops/SKILL.md:129-131 定價表（Opus $5/$25、Sonnet $3/$15、Haiku $1/$5）无 provenance 日期標記，若定價調整需人工全文搜尋更新。</li></ul><p>effort 硬編碼（3 處，風險低）：opus-pilot/SKILL.md:103、haiku-pilot/SKILL.md:96、sonnet-pilot/SKILL.md:132 — 均已 cite <code>.claude/refs/pilot-shared-preflights.md §E</code> 作 canonical source，屬「規則型引用」非裸寫死，風險可控。</p><h2 id="_4-dead-path-機械驗證" tabindex="-1">4. Dead path 機械驗證 <a class="header-anchor" href="#_4-dead-path-機械驗證" aria-label="Permalink to &quot;4. Dead path 機械驗證&quot;">​</a></h2><p><strong>結論：0 個真正失效引用。</strong> 初步 grep 命中 18 筆疑似 dead path，逐一 <code>test -f</code> 後發現全部是<strong>相對於 workspace root 的 bash 命令路徑</strong>（如 <code>scripts/healthcheck.sh</code>、<code>scripts/measure.sh</code>、<code>scripts/paywall_bypass.py</code>），而非 skill 目錄本地相對路徑；經 <code>ls /Users/zeuik/cc-workspace/scripts/</code> 核對全部檔案實際存在。<code>harness-meta/SKILL.md:167</code> 的 <code>research/agent-harness/dream-YYYY-MM-DD.md</code> 為輸出檔名模板（日期佔位符），非死連結。</p><p><strong>隱性風險（非「dead」但屬弱模型陷阱）</strong>：多個 SKILL.md（autoload-evolution、autoresearch、fable-pilot、fable5-harness、harness-meta、media-research、media-transcribe、multi-mode-skill、review-hub、ship-review、spec-implement、verified-merge）內的 <code>bash scripts/xxx.sh</code> 命令<strong>均隱含假設 cwd = workspace root</strong>，SKILL.md 內文無顯式聲明此前提。若弱模型 sub-agent 在非 root cwd（如已 cd 進某子目錄）執行，會得到 &quot;No such file or directory&quot; 且無自我糾錯線索（找不到會誤判為腳本不存在而非 cwd 錯誤）。建議：至少一處 SKILL.md 加註「假設 cwd = workspace root，執行前 pwd 確認」。</p><h2 id="_5-結構完整性缺失" tabindex="-1">5. 結構完整性缺失 <a class="header-anchor" href="#_5-結構完整性缺失" aria-label="Permalink to &quot;5. 結構完整性缺失&quot;">​</a></h2><ul><li><strong><code>fable5-harness</code></strong>：缺 <code>METADATA.json</code> 與 <code>GOTCHAS.md</code>（其餘 30 個 skill 均兩者齊備）。此 skill 屬四層行為契約入口，缺 METADATA.json 意味它未被納入某些依賴自動化流程（如 skill-evolution:scan 若依賴 METADATA.json 判讀 roster，此 skill 可能被漏掃）；缺 GOTCHAS.md 意味無已知失敗模式記錄，長期自主運作若踩坑無處查詢。</li></ul><h2 id="_6-弱模型誤讀風險-無判準抽象指令" tabindex="-1">6. 弱模型誤讀風險：無判準抽象指令 <a class="header-anchor" href="#_6-弱模型誤讀風險-無判準抽象指令" aria-label="Permalink to &quot;6. 弱模型誤讀風險：無判準抽象指令&quot;">​</a></h2><p>全文搜尋常見模糊詞（適當地/妥善/盡量/合理/清晰/優雅等），<strong>命中率遠低於預期</strong>——workspace 既有規則（output-discipline.md、core.md）已推動 skill 作者普遍採用量化門檻寫法（如 finops CDN hit rate ≥90%/95%/97%）。抽樣後 top 候選（非 10 例，僅 6 例達標，其餘為 template 佔位符或已有數字定義而排除）：</p><ol><li><code>pilot-review/SKILL.md:150</code> — 「這個方案的 LLM 使用是否合理？」（D1 cost 審查 prompt）無 token/次數門檻定義「合理」。</li><li><code>pilot-review/SKILL.md:183</code> — 「可維護性：命名清晰、不必要的複雜度」（D2 品質審查 prompt）&quot;清晰&quot;/&quot;不必要&quot;無 lint 規則或範例錨定。</li><li><code>pilot-review/SKILL.md:221</code> — 「有沒有更好的架構選擇？」（D3 架構審查 prompt）無比較基準或 ADR 模板外的具體評分軸。</li><li><code>quality-pipeline/SKILL.md:195</code> — 「輸出格式（簡潔）」未 cite output-discipline.md 150 字上限，讀者需自行猜測「簡潔」程度。</li><li><code>finops/SKILL.md:71</code> — 「多雲套利審慎」（表格描述，非執行指令）&quot;審慎&quot; 無操作定義，僅暗示需完整 ROI 計算但未給觸發門檻。</li><li><code>autoload-evolution/SKILL.md:262</code> — 「不得自行評估規則變更品質；必須委派 reviewer agent」本身是防範模糊自評的<strong>正例</strong>（非模糊指令，收錄以對照說明此 skill 已自我修正該風險模式）。</li></ol><p><strong>結論</strong>：模糊指令並非本次稽核最大風險源；真正弱模型風險集中在 <strong>#2 trigger 重疊</strong>（四對職責相近 skill 缺正向決策樹）與 <strong>#3 版本硬編碼 description</strong>（4 個 pilot skill 觸發詞穩定但基準內容會隨模型世代默默過期，無自動偵測）。</p>',23)])])}const m=t(d,[["render",r]]);export{h as __pageData,m as default};
